mapper.select:
SELECT  FROM scheduled_task_run
WHERE workspace_id = #{workspaceId} AND trigger_key = #{triggerKey}
LIMIT 1

SELECT  FROM scheduled_task_run
WHERE workspace_id = #{workspaceId} AND scheduled_task_id = #{scheduledTaskId}
ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT  FROM scheduled_task_run
WHERE status = 'STARTING' AND gmt_modified < #{before}
ORDER BY gmt_modified ASC, id ASC
LIMIT #{limit}

SELECT  FROM scheduled_task_run
WHERE status IN ('QUEUED', 'WAITING_EXECUTOR') AND gmt_modified < #{before}
ORDER BY scheduled_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE scheduled_task_run SET error = 'CANCEL_PENDING', modifier_id = #{modifierId}, version = version + 1
WHERE workspace_id = #{workspaceId} AND id = #{id} AND status NOT IN ('SUCCEEDED','FAILED','TIMED_OUT','CANCELED','SKIPPED')
  AND version = #{expectedVersion}
